const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const phoenix = ee.Geometry.Point([-112.0740, 33.4484]); // Approximate center of Phoenix, Arizona
  const startDate = '2017-06-15';
  const endDate = '2017-06-22'; // Filter up to, but not including, this date for June 21st.

  // 2. Data Acquisition
  // Using ERA5-Land Hourly data for 2m air temperature.
  // The 'mean_2m_air_temperature' band is in Kelvin.
  let collection = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterBounds(phoenix)
    .filterDate(startDate, endDate)
    .select('mean_2m_air_temperature');

  // Check if the collection is empty
  const collectionSize = await collection.size().getInfo();
  if (collectionSize === 0) {
    console.log("No ERA5-Land Hourly data found for Phoenix within the specified date range.");
    console.log("C1");
    return;
  }
  console.log(`ERA5-Land Hourly images found: ${collectionSize}`);

  // Get the maximum temperature across all images in the collection for the period.
  // This will give us the highest recorded temperature in Kelvin within the region
  // and time frame.
  const maxTemperatureImage = collection.max();

  // 3. Processing & Calculation
  // Reduce the maximum temperature image to get the highest temperature value
  // at the Phoenix point. Scale is important for performance and accuracy.
  // ERA5-Land has ~11km resolution, so 1000m or 3000m scale is appropriate.
  const maxKelvin = await maxTemperatureImage.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: phoenix,
    scale: 1000, // Approximately 1km resolution for reduction
    maxPixels: 1e9
  }).get('mean_2m_air_temperature').getInfo();

  // Check for C3 (Calculation Failure - None/NaN)
  if (maxKelvin === null || isNaN(maxKelvin)) {
    console.log("Calculation failed: Could not retrieve max temperature from the region.");
    console.log("C3");
    return;
  }

  // Convert Kelvin to Fahrenheit: (K - 273.15) * 9/5 + 32
  const maxFahrenheit = (maxKelvin - 273.15) * (9 / 5) + 32;

  // 4. Validation & Final Answer
  const threshold = 110; // degrees Fahrenheit
  const reachedThreshold = maxFahrenheit >= threshold;

  console.log(`Max temperature in Phoenix (June 15-21, 2017): ${maxFahrenheit.toFixed(2)} °F`);

  if (reachedThreshold) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
